/* Force-included (after port/include/compat.h) into every file of U.EXE's C (SRC_U) and of
 * its OSI library's port (port/u/osilib) when they are compiled for the host.
 *
 * U.EXE and GAME.EXE are two DOS programs; the port links both into one executable, so
 * every public name of U is renamed U_<name> (urename.h, generated by port/tools/gen_u.py
 * from the sources) and U's main is U_main (port/u/urun.c runs it). */
#ifndef U_UPORT_H
#define U_UPORT_H

#include "urename.h"
#undef main
#define main U_main

/* the graphics driver MCGADRV.BIN, in C: DRV(o)(...) is UDRV_o(...) (SRC_U/u.h) */
#include "ugfx.h"

/* _CS: the noise of the monitor and of the gypsy's pattern is random bytes of U.EXE's own
 * code (MK_FP(_CS, rand() & 0xe00)): the port loads U.EXE's image, and _CS is the
 * segment of the module's code in it (PORT_U_FRAME, the module's frame, set by the build) */
uint16_t u_code_segment(uint16_t frame);
#ifdef PORT_U_FRAME
#define _CS u_code_segment(PORT_U_FRAME)
#endif

#endif
